def secure(prefix: str) -> None:
    """Isolamento por clínica, privilégios mínimos e auditoria imutável."""
    app, service = f"{prefix}_app", f"{prefix}_service"
    for t in TENANT_TABLES:
        op.execute(f"ALTER TABLE {t} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {t} FORCE ROW LEVEL SECURITY")
        op.execute(f"CREATE POLICY tenant_isolation ON {t} USING (tenant_id = {TENANT_EXPR}) "
                   f"WITH CHECK (tenant_id = {TENANT_EXPR})")
    for s in SCHEMAS:
        op.execute(f"GRANT USAGE ON SCHEMA {s} TO {app}, {service}")
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA {s} TO {app}, {service}")
        op.execute(f"GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA {s} TO {app}, {service}")
        # tabelas de migrações futuras recebem os mesmos privilégios
        op.execute(f"ALTER DEFAULT PRIVILEGES IN SCHEMA {s} GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES "
                   f"TO {app}, {service}")
        op.execute(f"ALTER DEFAULT PRIVILEGES IN SCHEMA {s} GRANT USAGE, SELECT ON SEQUENCES TO {app}, {service}")
    # catálogo de permissões: leitura pela API; escrita só pelo serviço (manifestos)
    op.execute(f"REVOKE INSERT, UPDATE, DELETE ON auth.permissions FROM {app}")
    # auditoria: somente inserção e leitura — para todos, inclusive o dono do esquema
    op.execute(f"REVOKE UPDATE, DELETE, TRUNCATE ON audit.audit_log FROM {app}, {service}")
    op.execute("""CREATE FUNCTION audit.forbid_change() RETURNS trigger LANGUAGE plpgsql AS $$
                  BEGIN RAISE EXCEPTION 'audit_log é somente inserção'; END $$""")
    op.execute("""CREATE TRIGGER audit_log_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON audit.audit_log
                  FOR EACH STATEMENT EXECUTE FUNCTION audit.forbid_change()""")
    # resolução do código da organização no login (antes de haver tenant na sessão)
    op.execute("""CREATE FUNCTION tenancy.resolve_organization(p_code text) RETURNS uuid
                  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, tenancy AS $$
                  SELECT id FROM tenancy.organizations WHERE code = lower(p_code) AND active $$""")
    op.execute("REVOKE ALL ON FUNCTION tenancy.resolve_organization(text) FROM PUBLIC")
    op.execute(f"GRANT EXECUTE ON FUNCTION tenancy.resolve_organization(text) TO {app}, {service}")
